/**
 * TPSI — Florida Republican Gubernatorial Primary
 * County-level baseline projection · Election August 18, 2026
 *
 * GENERATED by scripts/gen_fl_forecast.mjs from app/floridaprimary/flData.json.
 * DO NOT EDIT BY HAND — regenerate from the model pipeline.
 *
 * READ BEFORE USING COUNTY SHARES
 * The county layer is a *decomposition* of the statewide model, not 67
 * independent estimates: county shares are the statewide numbers reweighted by
 * each county's demographic composition, so summing the counties returns the
 * statewide topline exactly and adds no information to it. Statewide
 * probabilities must come from STATEWIDE_FORECAST, never from aggregating
 * county intervals — county errors share one dominant statewide swing term,
 * so adding their variances in quadrature understates the real spread by
 * roughly an order of magnitude.
 *
 * The county estimates carry almost no local sample: 476 interviews spread
 * across 67 counties, a median of 3 per county and 27 counties at one or
 * fewer. They are also over-smoothed — demographic post-stratification cannot
 * reproduce home-county effects, media markets or ballot-order effects, so
 * between-county dispersion here is narrower than a real primary would show.
 * 61 of 67 counties have a 90% margin interval that crosses zero.
 *
 * `projectedTurnout` is the load-bearing field and is materially more reliable
 * than any share: it derives from R registration and historical primary
 * turnout, not from the survey. It is what lets the board estimate how much
 * vote is outstanding and where.
 */

export type CandidateKey = "donalds" | "fishback" | "collins" | "renner" | "other";

/** Every key except the residual bucket. */
export type NamedCandidateKey = Exclude<CandidateKey, "other">;

/** Ballot-order-independent display order: model rank at the time of build. */
export const CANDIDATE_ORDER: NamedCandidateKey[] = ["donalds", "fishback", "collins", "renner"];

/** Display order plus the residual bucket, for anything that must total 100. */
export const ALL_CANDIDATE_KEYS: CandidateKey[] = [...CANDIDATE_ORDER, "other"];

