export type Region =
  | "South Florida Metro/Keys"
  | "Tampa Bay"
  | "Atlantic/Treasure Coast"
  | "Northeast FL"
  | "Southwest Gulf/Interior"
  | "Central I-4/Orlando"
  | "Big Bend/North Central"
  | "Northwest Panhandle";

export interface CountyForecast {
  /** 5-digit state+county FIPS code */
  fips: string;
  name: string;
  region: Region;
  /** Modelled Republican primary ballots cast */
  projectedTurnout: number;
  /** Percent of the projected statewide electorate */
  shareOfElectorate: number;
  /** Vote shares, percent of all ballots cast in county */
  donalds: number;
  fishback: number;
  collins: number;
  renner: number;
  other: number;
  /** donalds − fishback, percentage points */
  margin: number;
  leader: CandidateKey;
  runnerUp: CandidateKey;
  /** 90% interval on `margin` */
  ci90: [number, number];
  /** True when ci90 straddles zero — do not report a county winner */
  tooCloseToCall: boolean;
  donaldsVotes: number;
  fishbackVotes: number;
  collinsVotes: number;
  rennerVotes: number;
  otherVotes: number;
  /** Completed interviews falling in this county. Frequently 0 or 1. */
  interviews: number;
}

export interface StatewideForecast {
  projectedTurnout: number;
  donalds: number;
  fishback: number;
  collins: number;
  renner: number;
  other: number;
  /** donalds − fishback, percentage points */
  margin: number;
  donaldsVotes: number;
  fishbackVotes: number;
  collinsVotes: number;
  rennerVotes: number;
  otherVotes: number;
  /** Simulated probability each candidate finishes first */
  winProbability: Record<Exclude<CandidateKey, "other">, number>;
  medianMargin: number;
  /** 90% interval on the simulated margin */
  margin90: [number, number];
  /** SD of the simulated Donalds−Fishback margin, percentage points */
  marginSd: number;
}

export interface TurnoutModel {
  registeredRepublicans: number;
  /** Ballots already banked by mail and early vote at model build */
  bankedBallots: number;
  projected: number;
  pctOfRegistered: number;
}

export interface ForecastMeta {
  model: string;
  electionDate: string;
  fieldDates: string;
  interviewsReported: number;
  marginOfError: number;
  countiesTooCloseToCall: number;
  raceRule: string;
}

